2	import { useEffect, useMemo, useRef, useState } from "react";
3	import { useSessionStore } from "@/stores/sessionStore";
4	import { modeStyle } from "@/lib/mode-style";
5	import { isEditableTarget } from "@/lib/shortcuts";
6	import { Dots } from "@/components/ui/Dots";
7	import type { Session } from "@/lib/types";
8	
9	// Workbench Wave 4 — VSCode-style editor tab strip (rewrite of Wave 1).
10	//
11	// The tab bar no longer floods every session into a tab. It renders ONLY the
12	// open editor tabs, exactly like VSCode:
13	//   • pinned tabs (store.pinnedSessionIds, ordered)
14	//   • + the single preview tab (store.previewSessionId), if any and not
15	//     already pinned — shown italic / dimmed to read as "temporary".
16	//
17	// Interaction:
18	//   • single-click a tab → loadSession (plain switch; a preview tab stays
19	//     preview)
20	//   • double-click the preview tab → pinSession (keep it open permanently)
21	//   • each tab has a × close → closeTab (removes from pinned / clears
22	//     preview; if it was active, switches to a neighbor)
23	//   • ⌘1–9 jump to the Nth OPEN tab (pinned then preview) — not all sessions
24	//   • emerald unread dot when a run finished here while the user was away
25	//     (R3), distinct from the blue running pulse.
26	//
27	// The full session list lives in the left SessionSidebar (incl. its archived
28	// view). The strip only renders pinned + preview tabs plus a "＋" new entry.
29	// A redundant "+" sits next to it as a secondary new-session entry.
30	
31	export function SessionTabs() {
32	  const activeId = useSessionStore((s) => s.session?.id ?? null);
33	  const pinnedIds = useSessionStore((s) => s.pinnedSessionIds);
34	  const previewId = useSessionStore((s) => s.previewSessionId);
35	  const loadSession = useSessionStore((s) => s.loadSession);
36	  const pinSession = useSessionStore((s) => s.pinSession);
37	  const closeTab = useSessionStore((s) => s.closeTab);
38	  const newConversation = useSessionStore((s) => s.newConversation);
39	  const sessionsRevision = useSessionStore((s) => s.sessionsRevision);
40	  const runningIds = useSessionStore((s) => s.runningSessionIds);
41	  const unreadIds = useSessionStore((s) => s.unreadSessionIds);
42	
43	  // Zero-latency running state for the session the user is actually looking
44	  // at: derive it from the live node map instead of waiting up to 1.5s for
45	  // the /api/runs poll. Non-active sessions still rely on the poll snapshot.
46	  const activeRunning = useSessionStore((s) =>
47	    Object.values(s.nodes).some((n) => n.status === "streaming"),
48	  );
49	  const isRunning = (id: string) =>
50	    runningIds.has(id) || (id === activeId && activeRunning);
51	
52	  // Cache the full session list so we can resolve open tab ids → Session
53	  // objects (title, mode). Same watch contract as the sidebar/picker.
54	  const [byId, setById] = useState<Record<string, Session>>({});
55	  useEffect(() => {
56	    let cancelled = false;
57	    fetch("/api/sessions")
58	      .then((r) => r.json())
59	      .then((data) => {
60	        if (cancelled) return;
61	        const map: Record<string, Session> = {};
62	        for (const s of (data.sessions ?? []) as Session[]) map[s.id] = s;
63	        setById(map);
64	      })
65	      .catch(() => {
66	        /* keep last-known map on transient failure */
67	      });
68	    return () => {
69	      cancelled = true;
70	    };
71	  }, [activeId, sessionsRevision]);
72	
73	  // The ordered list of OPEN tabs: pinned (in order) then the preview tab
74	  // (if it isn't already pinned). Drives both render and ⌘1–9.
75	  const openIds = useMemo(() => {
76	    const ids = [...pinnedIds];
77	    if (previewId && !pinnedIds.includes(previewId)) ids.push(previewId);
78	    // Only keep ids we can actually resolve to a session (defends against a
79	    // just-deleted id lingering for a tick before the store evicts it).
80	    return ids.filter((id) => byId[id]);
81	  }, [pinnedIds, previewId, byId]);
82	
83	  // ⌘1–9 (and Ctrl+1–9 off-mac) jump to the Nth open tab. Ignored while
84	  // typing so digits with a held modifier still reach inputs.
85	  useEffect(() => {
86	    const onKey = (e: KeyboardEvent) => {
87	      if (!(e.metaKey || e.ctrlKey) || e.altKey || e.shiftKey) return;
88	      if (e.key < "1" || e.key > "9") return;
89	      if (isEditableTarget(e.target)) return;
90	      const id = openIds[Number(e.key) - 1];
91	      if (!id) return;
92	      e.preventDefault();
93	      if (id !== activeId) loadSession(id);
94	    };
95	    window.addEventListener("keydown", onKey);
96	    return () => window.removeEventListener("keydown", onKey);
97	  }, [openIds, activeId, loadSession]);
98	
99	  // Offset the strip to start right of the sidebar. We read the same
100	  // --trellis-sb var the content surfaces use (set in page.tsx), which
101	  // already folds in the mobile guard + collapsed state.
102	  // 移动端整条隐藏（hidden md:block）：tab 条与 hamburger 抽屉的会话列表
103	  // 功能重叠，还吃掉 2.25rem 纵向空间——手机上会话切换走抽屉。
104	  return (
105	    <div
106	      className="hidden md:block fixed top-12 right-0 z-30 h-9 bg-surface-canvas/85 backdrop-blur border-b border-line"
107	      style={{ left: "var(--trellis-sb, 0px)" }}
108	    >
109	      <div className="h-full flex items-stretch overflow-x-auto no-scrollbar px-2 gap-1">
110	        {openIds.length === 0 && (
111	          <div className="self-center pl-1 text-label text-ink-faint italic">
112	            搜索或＋新建打开会话，双击标签固定
113	          </div>
114	        )}
115	        {openIds.map((id, i) => {
116	          const s = byId[id];
117	          if (!s) return null;
118	          const isPreview = id === previewId && !pinnedIds.includes(id);
119	          return (
120	            <Tab
121	              key={id}
122	              session={s}
123	              active={id === activeId}
124	              preview={isPreview}
125	              running={isRunning(id)}
126	              unread={unreadIds.has(id)}
127	              shortcut={i + 1}
128	              onClick={() => {
129	                if (id !== activeId) loadSession(id);
130	              }}
131	              onDoubleClick={() => {
132	                if (isPreview) pinSession(id);
133	              }}
134	              onClose={() => closeTab(id)}
135	            />
136	          );
137	        })}
138	        <div className="self-center ml-auto pl-1 shrink-0 flex items-center gap-1">
139	          {/* Redundant secondary new-session entry. */}
140	          <button
141	            onClick={() => newConversation()}
142	            title="新会话（全新树）"
143	            aria-label="新会话"
144	            className="w-6 h-6 flex items-center justify-center rounded text-ink-muted hover:bg-surface-muted hover:text-ink-strong"
145	          >
146	            <span aria-hidden className="text-reading leading-none">＋</span>
147	          </button>
148	        </div>
149	      </div>
150	    </div>
151	  );
152	}
153	
154	function Tab({
155	  session,
156	  active,
157	  preview,
158	  running,
159	  unread,
160	  shortcut,
161	  onClick,
162	  onDoubleClick,
