200	            // unmistakably, active or not. Bottom sweep bar added below.
201	            "bg-accent-muted border-accent-line text-accent-ink font-medium"
202	          : unread
203	            ? // Finished-unread tint (unread hue) — loud but static.
204	              "bg-unread-muted border-unread-line text-unread-ink font-medium"
