449	export function deleteSession(id: string): void {
450	  const db = getDB();
451	  // Collect every claude session jsonl bound to this trellis session. project
452	  // stores one id per root (tree-shared); chat B-fork stores one per NODE — so
453	  // collect ALL non-null ids, not just roots, or B-fork transcripts leak. The
454	  // spawn cwd (sessionCwd) decides the encoded-cwd dir the jsonl lives in,
455	  // identical for every node in the session.
456	  const meta = db
457	    .prepare(
458	      "SELECT context_mode AS mode, workspace_path AS wp, origin FROM sessions WHERE id = ?",
459	    )
460	    .get(id) as
461	    | { mode: string; wp: string | null; origin: string }
462	    | undefined;
463	  const claudeIdRows = db
464	    .prepare(
465	      `SELECT claude_session_id FROM nodes
466	       WHERE session_id = ? AND claude_session_id IS NOT NULL`,
467	    )
468	    .all(id) as { claude_session_id: string }[];
469	  const codexIdRows = db
470	    .prepare(
471	      `SELECT DISTINCT codex_session_id FROM nodes
472	       WHERE session_id = ? AND codex_session_id IS NOT NULL`,
473	    )
474	    .all(id) as { codex_session_id: string }[];
475	  db.prepare("DELETE FROM sessions WHERE id = ?").run(id);
476	  // FK cascade nukes nodes/notes but the FTS virtual table isn't on the
477	  // FK graph — do it explicitly.
478	  ftsDeleteBySession(db, id);
479	  // cli-import 镜像的 jsonl 是用户的原始 CLI 历史，绝不能跟着删 —— 只清 DB 行。
480	  if (meta && meta.origin !== "cli-import") {
481	    const cwd = sessionCwd(meta.mode as Mode, meta.wp);
482	    for (const r of claudeIdRows) {
483	      try {
484	        fs.unlinkSync(claudeSessionPath(r.claude_session_id, cwd));
485	      } catch {
486	        // jsonl may have been moved/deleted manually — best effort.
487	      }
488	    }
489	    // codex rollouts leak the same way (linear codex chains share one sid —
490	    // hence DISTINCT). Path is found by id scan, cwd-independent.
491	    for (const r of codexIdRows) deleteCodexRollout(r.codex_session_id);
492	  }
493	}
494	
495	// Resume ids are provider-family-scoped — claude ids live in
496	// claude_session_id, codex ids in codex_session_id, and mock never resumes.
497	// Map a family to its column (null = no resumable column for this family).
498	function resumeColumnForFamily(family: ProviderFamily): string | null {
499	  if (family === "claude") return "claude_session_id";
500	  if (family === "codex") return "codex_session_id";
501	  return null; // mock
502	}
