504	// Family-dispatched "can this resume id still be honored?" check. claude keeps
505	// its historical convention: only validated when the caller passed a
506	// workspacePath (undefined = opted out). codex rollouts are cwd-independent —
507	// validate whenever asked (scan ~/.codex/sessions by id).
508	function resumeTargetExists(
509	  family: ProviderFamily,
510	  id: string,
511	  workspacePath?: string | null,
512	): boolean {
513	  if (family === "claude") {
514	    return workspacePath === undefined || claudeJsonlExists(id, workspacePath);
515	  }
516	  if (family === "codex") return codexRolloutExists(id);
517	  return true; // mock — unreachable (no resume column)
518	}

