1	"use client";
2	import {
3	  ReactFlow,
4	  ReactFlowProvider,
5	  Background,
6	  useReactFlow,
7	  useStore as useFlowStore,
8	  type Node,
9	  type Edge,
10	} from "@xyflow/react";
11	import { useMemo, useEffect, useState, useCallback } from "react";
12	import { useSessionStore } from "@/stores/sessionStore";
13	import { isEditableTarget } from "@/lib/shortcuts";
14	import { ChatNode, type ChildAnchor } from "./ChatNode";
15	import { ReferenceCard } from "./ReferenceCard";
16	import { AddNodeFAB } from "./AddNodeFAB";
17	import { BranchPopover } from "./BranchPopover";
18	import { Composer } from "./Composer";
19	import { Outline } from "./Outline";
20	import { TargetChip } from "./TargetChip";
21	import {
22	  useSelectionWithin,
23	  type SelectionInfo,
24	} from "@/hooks/useSelectionWithin";
25	import { layoutNodes, COMPACT_ZOOM_THRESHOLD } from "@/lib/layout";
26	import { buildNodeIndex } from "@/lib/node-index";
27	import { hiddenByCollapse } from "@/lib/collapsed";
28	
29	const nodeTypes = { chat: ChatNode, reference: ReferenceCard };
30	const NODE_WIDTH = 600;
31	const NODE_HEIGHT_ESTIMATE = 480;
32	const EMPTY_ANCHORS: ChildAnchor[] = [];
33	
34	export function Canvas({ onNodeFocus }: { onNodeFocus?: () => void } = {}) {
35	  return (
36	    <ReactFlowProvider>
37	      <CanvasInner onNodeFocus={onNodeFocus} />
38	    </ReactFlowProvider>
39	  );
40	}
41	
42	// (Previous READ_ZOOM / OVERVIEW_THRESHOLD constants removed: the
43	// auto-zoom-on-focus behavior was contributing to a feedback loop with the
44	// LoD threshold. Active-node focus now preserves the user's current zoom.)
45	
46	function CanvasInner({ onNodeFocus }: { onNodeFocus?: () => void }) {
47	  const nodeMap = useSessionStore((s) => s.nodes);
48	  const setNodePosition = useSessionStore((s) => s.setNodePosition);
49	  const activeNodeId = useSessionStore((s) => s.activeNodeId);
50	  const setActiveNode = useSessionStore((s) => s.setActiveNode);
51	  const collapsedNodeIds = useSessionStore((s) => s.collapsedNodeIds);
52	  const sessionId = useSessionStore((s) => s.session?.id);
53	  const { setCenter, getViewport, fitView } = useReactFlow();
54	
55	  // Folded subtrees disappear from the canvas — collapsed roots stay
56	  // visible (their "+N" badge invites re-expansion), but every
57	  // descendant is excluded from layout, flowNodes, and flowEdges.
58	  const hiddenIds = useMemo(
59	    () => hiddenByCollapse(collapsedNodeIds, nodeMap),
60	    [collapsedNodeIds, nodeMap],
61	  );
62	
63	  // First-mount nodes start at (0,0) and snap to dagre output on the
64	  // first layout pass — animating that flight from origin looks worse
65	  // than just popping into place. Gate the transform transition behind
66	  // this flag so subsequent re-layouts (collapse / streaming finish /
67	  // LoD threshold) slide smoothly without that initial fly-in.
68	  const [layoutReady, setLayoutReady] = useState(false);
69	
70	  // Per-node "peek": expand a compact card into its full form in place, on
71	  // the canvas, without jumping to the linear reader. Multiple can be open at
72	  // once. Folded into layoutKey so dagre reflows neighbors (the expanded card
73	  // is taller AND wider than a compact one — see layoutNodes' measured
74	  // width/height handling). Ids are per-session-unique (UUIDs), so a peeked id
75	  // from another session simply never matches the current node map — no reset
76	  // needed, and switching back to a session restores its peeked cards.
77	  const [peekedIds, setPeekedIds] = useState<Set<string>>(new Set());
78	  const togglePeek = useCallback((id: string) => {
79	    setPeekedIds((prev) => {
80	      const next = new Set(prev);
81	      if (next.has(id)) next.delete(id);
82	      else next.add(id);
83	      return next;
84	    });
85	  }, []);
86	
87	  // LoD-aware: layout shrinks when zoom drops below the threshold so
88	  // overview cards (compact form) sit close together — selector returns a
89	  // boolean so we only re-layout on threshold crossings, not every wheel.
90	  const isCompact = useFlowStore(
91	    (s) => s.transform[2] < COMPACT_ZOOM_THRESHOLD,
92	  );
93	
94	  // Re-layout when topology changes, when a node's status flips
95	  // (streaming → done → height stabilizes), or when LoD threshold crosses.
96	  // Streaming text deltas don't change this key, so layout doesn't thrash
97	  // on every chunk.
98	  const layoutKey = useMemo(
99	    () =>
100	      Object.values(nodeMap)
101	        .map((n) => `${n.id}:${n.parentId ?? "_"}:${n.status}`)
102	        .sort()
103	        .join("|") +
104	      (isCompact ? ":c" : ":f") +
105	      "|h=" +
106	      [...hiddenIds].sort().join(",") +
107	      "|p=" +
108	      [...peekedIds].sort().join(","),
109	    [nodeMap, isCompact, hiddenIds, peekedIds],
110	  );
111	
112	  const { getNodes } = useReactFlow();
113	
114	  useEffect(() => {
115	    const visibleNodes = Object.values(nodeMap).filter(
116	      (n) => !hiddenIds.has(n.id),
117	    );
118	    if (visibleNodes.length === 0) return;
119	    // Wait one tick so React Flow has rendered + measured heights of any
120	    // newly-added/changed nodes before we re-run Dagre. Peeked cards use a
121	    // fixed reserved footprint (see layoutNodes' forceFullIds), so a single
122	    // pass already reflows descendants correctly — no measurement retry needed.
123	    const t = window.setTimeout(() => {
124	      const heights = new Map<string, number>();
125	      for (const fn of getNodes()) {
126	        const h = fn.measured?.height;
127	        if (typeof h === "number" && h > 0) heights.set(fn.id, h);
128	      }
129	      const positions = layoutNodes(visibleNodes, heights, {
130	        compact: isCompact,
131	        forceFullIds: peekedIds,
132	      });
133	      for (const [id, pos] of positions) {
134	        const cur = nodeMap[id];
135	        if (!cur) continue;
136	        if (
137	          Math.abs(cur.position.x - pos.x) > 0.5 ||
138	          Math.abs(cur.position.y - pos.y) > 0.5
139	        ) {
140	          setNodePosition(id, pos);
141	        }
142	      }
143	      // After the first real dagre pass with measured heights, allow
144	      // subsequent transform changes to animate. Wait until the next
145	      // frame so the new positions paint before transitions arm.
146	      requestAnimationFrame(() => setLayoutReady(true));
147	    }, 60);
148	    return () => window.clearTimeout(t);
149	    // eslint-disable-next-line react-hooks/exhaustive-deps
150	  }, [layoutKey]);
151	
152	  // Pan smoothly to the active node whenever the user explicitly changes it.
153	  // Intentionally NOT depending on activeX/activeY: dagre re-layouts (e.g.
154	  // LoD threshold crossings) would otherwise re-fire setCenter every time
155	  // positions shift, and the resulting zoom changes can cascade back into
156	  // LoD toggles. Pan only when activeNodeId actually changes; preserve the
157	  // user's current zoom rather than auto-bumping to READ_ZOOM, which used to
158	  // form the other half of the LoD oscillation loop.
159	  const activeNode = activeNodeId ? nodeMap[activeNodeId] : null;
160	  useEffect(() => {
161	    if (!activeNode) return;
162	    const id = requestAnimationFrame(() => {
163	      const { zoom: cur } = getViewport();
164	      setCenter(
165	        activeNode.position.x + NODE_WIDTH / 2,
166	        activeNode.position.y + NODE_HEIGHT_ESTIMATE / 2,
167	        { zoom: cur, duration: 500 },
168	      );
169	    });
170	    return () => cancelAnimationFrame(id);
171	    // eslint-disable-next-line react-hooks/exhaustive-deps
172	  }, [activeNodeId]);
173	
174	  // Re-fit view when switching sessions — fitView prop only fires on mount.
175	  // Also drop the layout-ready flag so the new session's first dagre
176	  // pass doesn't animate cards flying in from origin.
177	  //
178	  // When Canvas is remounting because the user just left the linear thread
179	  // (viewMode → "canvas"), activeNodeId is already pointing at the node
180	  // we want to land on (set by setViewMode). Skip the auto-land in that
181	  // case so the activeNodeId effect can pan/zoom to that node without
182	  // being overwritten by a global fit a few frames later.
183	  //
184	  // 80/20 landing: when activeNodeId is null at session load (fresh
185	  // hydrate / page refresh / picker switch), pan to the freshest piece
186	  // of work — store's lastEditedNodeId — instead of fitView'ing the
187	  // whole tree. fitView with a deep tree drops the user at the root or
188	  // a wide overview that's almost never what they came back for. We read
189	  // store state inside the timeout (after dagre has laid out positions
190	  // ~60ms in) and fall back to fitView only when there's no candidate.
191	  useEffect(() => {
192	    if (!sessionId) return;
193	    setLayoutReady(false);
194	    if (activeNodeId) return;
195	    const t = window.setTimeout(() => {
196	      const state = useSessionStore.getState();
197	      const fresh =
198	        state.lastEditedNodeId && state.nodes[state.lastEditedNodeId];
199	      if (fresh && fresh.position) {
200	        const { zoom: cur } = getViewport();
201	        setCenter(
202	          fresh.position.x + NODE_WIDTH / 2,
203	          fresh.position.y + NODE_HEIGHT_ESTIMATE / 2,
204	          { zoom: cur, duration: 400 },
205	        );
206	      } else {
207	        fitView({ padding: 0.15, duration: 400 });
208	      }
209	    }, 120);
210	    return () => window.clearTimeout(t);
211	    // activeNodeId is intentionally a snapshot read at session-change /
212	    // mount time — we don't want every later setActiveNode to re-fire
213	    // this layout reset.
214	    // eslint-disable-next-line react-hooks/exhaustive-deps
215	  }, [sessionId, fitView, setCenter, getViewport]);
216	
217	  // F key → fit to overview. Skip when typing in inputs.
218	  useEffect(() => {
219	    const onKey = (e: KeyboardEvent) => {
220	      if (isEditableTarget(e.target)) return;
221	      if ((e.key === "f" || e.key === "F") && !e.metaKey && !e.ctrlKey) {
222	        e.preventDefault();
223	        fitView({ padding: 0.15, duration: 400 });
224	      }
225	    };
226	    window.addEventListener("keydown", onKey);
227	    return () => window.removeEventListener("keydown", onKey);
228	  }, [fitView]);
229	
230	  // Derive childAnchors per parent once at the canvas level, so each ChatNode
231	  // doesn't have to subscribe to the entire nodes map and re-filter on every
232	  // streaming delta. Using an empty-array constant for parents with no
233	  // anchored children keeps the prop reference stable across renders.
234	  const childAnchorsByParent = useMemo(() => {
235	    const map = new Map<string, ChildAnchor[]>();
236	    for (const n of Object.values(nodeMap)) {
237	      if (!n.parentId || !n.parentAnchor?.selectedText) continue;
238	      const arr = map.get(n.parentId) ?? [];
239	      arr.push({ text: n.parentAnchor.selectedText, childId: n.id });
240	      map.set(n.parentId, arr);
241	    }
242	    return map;
243	  }, [nodeMap]);
244	
245	  const nodeIndices = useMemo(() => buildNodeIndex(nodeMap), [nodeMap]);
246	
247	  // Per-node descendant counts in one pass — drives the "▶ N" / "▼ N"
248	  // chip on cards. Build a children map then DFS post-order so each id
249	  // accumulates its subtree size in linear time.
250	  const descendantCounts = useMemo(() => {
251	    const childrenByParent = new Map<string, string[]>();
252	    for (const n of Object.values(nodeMap)) {
253	      if (!n.parentId) continue;
254	      const arr = childrenByParent.get(n.parentId) ?? [];
255	      arr.push(n.id);
256	      childrenByParent.set(n.parentId, arr);
257	    }
258	    const counts: Record<string, number> = {};
259	    const visit = (id: string): number => {
260	      if (counts[id] !== undefined) return counts[id];
261	      const kids = childrenByParent.get(id) ?? [];
262	      let sum = 0;
263	      for (const k of kids) sum += 1 + visit(k);
264	      counts[id] = sum;
265	      return sum;
266	    };
267	    for (const id of Object.keys(nodeMap)) visit(id);
268	    return counts;
269	  }, [nodeMap]);
270	
271	  const flowNodes: Node[] = useMemo(
272	    () =>
273	      Object.values(nodeMap)
274	        .filter((n) => !hiddenIds.has(n.id))
275	        .map((n) => {
276	          const isReference = n.kind === "reference";
277	          const index = nodeIndices[n.id] ?? 0;
278	          const descendantCount = descendantCounts[n.id] ?? 0;
279	          const collapsed = collapsedNodeIds.has(n.id);
280	          return {
281	            id: n.id,
282	            type: isReference ? "reference" : "chat",
283	            position: n.position,
284	            // Peeked cards float above neighbors — a wide expanded card can
285	            // briefly overlap during reflow, and it should never sit under the
286	            // small cards around it.
287	            zIndex: peekedIds.has(n.id) ? 1000 : undefined,
288	            data: isReference
289	              ? {
290	                  node: n,
291	                  isActive: n.id === activeNodeId,
292	                  index,
293	                  descendantCount,
294	                  collapsed,
295	                }
296	              : {
297	                  node: n,
298	                  isActive: n.id === activeNodeId,
299	                  childAnchors:
300	                    childAnchorsByParent.get(n.id) ?? EMPTY_ANCHORS,
301	                  index,
302	                  descendantCount,
303	                  collapsed,
304	                  isPeeked: peekedIds.has(n.id),
305	                  onTogglePeek: togglePeek,
306	                },
307	            draggable: false,
308	          };
309	        }),
310	    [
311	      nodeMap,
312	      activeNodeId,
313	      childAnchorsByParent,
314	      nodeIndices,
315	      hiddenIds,
316	      descendantCounts,
317	      collapsedNodeIds,
318	      peekedIds,
319	      togglePeek,
320	    ],
321	  );
322	
323	  const flowEdges: Edge[] = useMemo(
324	    () =>
325	      Object.values(nodeMap)
326	        .filter((n) => n.parentId && !hiddenIds.has(n.id))
327	        .map((n) => ({
328	          id: `e-${n.id}`,
329	          source: n.parentId!,
330	          target: n.id,
331	          type: "default",
332	        })),
333	    [nodeMap, hiddenIds],
334	  );
335	
336	  const liveSelection = useSelectionWithin();
337	  const [popover, setPopover] = useState<{
338	    selection: SelectionInfo;
339	    expanded: boolean;
340	  } | null>(null);
341	
342	  useEffect(() => {
343	    setPopover((prev) => {
344	      // A canvas card only exposes a selectable body when it renders full —
345	      // peeked, streaming, or an unsuperseded error (mirrors ChatNode's
346	      // showCompact).
347	      const rendersFull = (id: string) => {
348	        const n = nodeMap[id];
349	        return (
350	          !!n &&
351	          (peekedIds.has(id) ||
352	            n.status === "streaming" ||
353	            (n.status === "error" && (descendantCounts[id] ?? 0) === 0))
354	        );
355	      };
356	      // Expanded popover stays sticky — it composes off snapshots
357	      // (selection.text/rect), so a collapsing card mustn't discard in-progress
358	      // typing. Checked FIRST so the close-gate below only touches the
359	      // collapsed (two-button) popover.
360	      if (prev?.expanded) return prev;
361	      // Collapsed popover whose card stopped rendering full (e.g. the user hit
362	      // 收起 without dismissing first): its selectable body is gone, so close
363	      // it — otherwise the buttons hang on the canvas.
364	      if (prev && !rendersFull(prev.selection.nodeId)) return null;
365	      if (liveSelection && rendersFull(liveSelection.nodeId)) {
366	        // Keep the same object when the selection is unchanged, so nodeMap
367	        // ticks (e.g. another node streaming) don't churn a re-render while a
368	        // popover is open. (prev is non-expanded here — expanded returned above.)
369	        if (prev && prev.selection === liveSelection) return prev;
370	        return { selection: liveSelection, expanded: false };
371	      }
372	      return null;
373	    });
374	  }, [liveSelection, peekedIds, nodeMap, descendantCounts]);
375	
376	  const closePopover = () => {
377	    setPopover(null);
378	    window.getSelection()?.removeAllRanges();
379	  };
380	  const expandPopover = () => {
381	    setPopover((prev) => (prev ? { ...prev, expanded: true } : prev));
382	  };
383	
384	  return (
385	    <>
386	      <div
387	        className={`w-screen h-screen pt-12 md:pt-[5.25rem] bg-gradient-to-b from-surface-canvas via-surface to-surface-muted${
388	          layoutReady ? " canvas-layout-ready" : ""
389	        }`}
390	        // Wave 4: shift the canvas right of the explorer sidebar (var set in
391	        // page.tsx; 0 on mobile / when collapsed). box-border keeps the
392	        // element 100vw while the inner ReactFlow area shrinks by the pad.
393	        // paddingBottom 同理让出终端面板高度，否则画布下缘被面板盖住。
394	        style={{
395	          paddingLeft: "var(--trellis-sb, 0px)",
396	          paddingBottom: "var(--trellis-term-h, 0px)",
397	          boxSizing: "border-box",
398	        }}
399	      >
400	        <ReactFlow
401	          nodes={flowNodes}
402	          edges={flowEdges}
403	          nodeTypes={nodeTypes}
404	          minZoom={0.2}
405	          maxZoom={1.5}
406	          proOptions={{ hideAttribution: true }}
407	          defaultEdgeOptions={{ type: "smoothstep", style: { strokeWidth: 1.5 } }}
408	          onNodeClick={(_, node) => {
409	            setActiveNode(node.id);
410	            onNodeFocus?.();
411	          }}
412	          onPaneClick={() => fitView({ padding: 0.15, duration: 400 })}
413	        >
414	          <Background gap={22} size={1} color="#d6d3d1" className="opacity-60 dark:opacity-[0.18]" />
415	        </ReactFlow>
416	      </div>
417	      {/* Always-visible "fit view" floating button — replaces F key on mobile */}
418	      <button
419	        onClick={() => fitView({ padding: 0.15, duration: 400 })}
420	        className="fixed top-[60px] right-3 z-30 w-10 h-10 rounded-full bg-surface border border-line shadow-raise flex items-center justify-center text-ink-muted hover:bg-surface-muted active:scale-95 transition-transform"
421	        title="回到全局视图 (F / 点击空白)"
422	        aria-label="回到全局视图"
423	      >
424	        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
425	          <path d="M3 9V3h6M21 9V3h-6M3 15v6h6M21 15v6h-6" />
426	        </svg>
427	      </button>
428	      {popover?.selection && (
429	        <BranchPopover
430	          selection={popover.selection}
431	          expanded={popover.expanded}
432	          onExpand={expandPopover}
433	          onClose={closePopover}
434	        />
435	      )}
436	      <AddNodeFAB />
437	      <DockedComposer />
438	      <Outline />
439	    </>
440	  );
441	}
442	
443	// #3: the tree view's FIXED bottom input region. Follow-ups used to live
444	// inside each card's footer, which jumps around as dagre re-layouts during
445	// streaming — this bar is docked to the viewport so the input never moves.
446	// It continues from the active node (falling back to the freshest work /
447	// root); the target chip makes the branch point explicit.
448	function DockedComposer() {
449	  const nodeMap = useSessionStore((s) => s.nodes);
450	  const activeNodeId = useSessionStore((s) => s.activeNodeId);
451	  const lastEditedNodeId = useSessionStore((s) => s.lastEditedNodeId);
452	  const rootNodeId = useSessionStore((s) => s.session?.rootNodeId);
453	  const nodeIndices = useMemo(() => buildNodeIndex(nodeMap), [nodeMap]);
454	
455	  const target =
456	    (activeNodeId ? nodeMap[activeNodeId] : undefined) ??
457	    (lastEditedNodeId ? nodeMap[lastEditedNodeId] : undefined) ??
458	    (rootNodeId ? nodeMap[rootNodeId] : undefined) ??
459	    null;
460	
461	  const targetLabel = target
462	    ? target.topicLabel ??
463	      (target.kind === "reference"
464	        ? "参考材料"
465	        : target.question.length > 24
466	          ? `${target.question.slice(0, 24)}…`
467	          : target.question)
468	    : null;
469	
470	  return (
471	    <div
472	      className="fixed right-0 z-20"
473	      // S1 P1: docked composer 坐在终端面板之上（--trellis-term-h 由
474	      // TerminalPanel 发布；关闭时 0px = 贴底，与原来一致）。
475	      style={{
476	        left: "var(--trellis-sb, 0px)",
477	        bottom: "var(--trellis-term-h, 0px)",
478	      }}
479	    >
480	      <div className="border-t border-line/80 bg-surface-canvas/95 backdrop-blur">
481	        <div className="max-w-2xl mx-auto px-4">
482	          {target && (
483	            <TargetChip
484	              icon="⑂"
485	              verb="回复"
486	              index={nodeIndices[target.id] ?? "?"}
487	              label={targetLabel ?? ""}
488	              hint="点卡片可切换目标"
489	            />
490	          )}
491	          <Composer targetNode={target} placeholder="对选中节点继续追问…" />
492	        </div>
493	      </div>
494	    </div>
495	  );
496	}
