527	// React.memo with custom comparison so streaming a single node doesn't
528	// re-render every other node on every token. Hot path: handleStreamEvent
529	// in sessionStore preserves identity for non-streaming nodes (only the
530	// streaming node's object is replaced), so `prev.node === next.node`
531	// catches them. childAnchors is rebuilt by the Canvas selector on every
532	// nodeMap change but is small per-parent — value-compare it.
533	export const ChatNode = memo(ChatNodeImpl, (prev, next) => {
534	  if (prev.data.node !== next.data.node) return false;
535	  if (prev.data.isActive !== next.data.isActive) return false;
536	  if (prev.data.collapsed !== next.data.collapsed) return false;
537	  if (prev.data.isPeeked !== next.data.isPeeked) return false;
538	  if (prev.data.descendantCount !== next.data.descendantCount) return false;
539	  const a = prev.data.childAnchors;
540	  const b = next.data.childAnchors;
541	  if (a !== b) {
542	    if (a.length !== b.length) return false;
543	    for (let i = 0; i < a.length; i++) {
544	      if (a[i].childId !== b[i].childId || a[i].text !== b[i].text) return false;
545	    }
546	  }
547	  return true;
548	});
