// lib/markdown-cache.tsx (client)
import { createElement, type ReactNode } from "react";

type CacheEntry = { response: string; elements: ReactNode };
const cache = new Map<string, CacheEntry>();
const CAP = 300;

export function getMarkdown(nodeId: string, response: string, render: () => ReactNode): ReactNode {
  const hit = cache.get(nodeId);
  if (hit && hit.response === response) {
