import { unified } from "unified";
import remarkParse from "remark-parse";
import remarkRehype from "remark-rehype";
import rehypeRaw from "rehype-raw";
import rehypeKatex from "rehype-katex";
import rehypeHighlight from "rehype-highlight";
import { toJsxRuntime } from "hast-util-to-jsx-runtime";
import { Fragment, jsx, jsxs } from "react/jsx-runtime";
import { visit } from "unist-util-visit";
import { urlAttributes } from "html-url-attributes";
import { MARKDOWN_REMARK_PLUGINS } from "./markdown-plugins";
import { MD_COMPONENTS, MD_URL_TRANSFORM } from "./md-components";
import type { Root } from "hast";

// One processor for the done-state pipeline (rehypeRaw + katex + highlight).
const processor = unified()
  .use(remarkParse)
  .use(MARKDOWN_REMARK_PLUGINS)
  .use(remarkRehype, { allowDangerousHtml: true })
  .use(rehypeRaw)
  .use(rehypeKatex)
  .use(rehypeHighlight);

// Hast cache: keyed by node id; entry holds the response string it was built
// from so a changed response (retry / refresh / stream done) re-renders.
// LRU-capped — rendered trees for big sessions are ~MBs total, fine to keep
// a few hundred.
type Entry = { response: string; hast: Root };
const cache = new Map<string, Entry>();
const CAP = 250;

function getHast(nodeId: string, response: string): Root {
  const hit = cache.get(nodeId);
  if (hit && hit.response === response) {
    cache.delete(nodeId);
    cache.set(nodeId, hit);
    return hit.hast;
  }
  const hast = processor.run(processor.parse(response)) as Root;
  cache.set(nodeId, { response, hast });
  if (cache.size > CAP) {
    const oldest = cache.keys().next().value;
    if (oldest !== undefined) cache.delete(oldest);
  }
  return hast;
}

// Faithful copy of react-markdown v10's post()-transform: raw nodes → text
// (rehypeRaw already consumed real HTML; this only mops leftovers) and
// urlTransform applied to URL-bearing attributes.
function applyUrlTransform(tree: Root) {
  visit(tree, (node, index, parent) => {
    if (node.type === "raw" && parent && typeof index === "number") {
      parent.children[index] = { type: "text", value: (node as any).value };
      return index;
    }
    if (node.type === "element") {
      for (const key in urlAttributes) {
        if (Object.hasOwn(urlAttributes, key) && Object.hasOwn(node.properties, key)) {
          const value = node.properties[key];
          const test = urlAttributes[key];
          if (test === null || test.includes(node.tagName)) {
            node.properties[key] = MD_URL_TRANSFORM(String(value || ""), key as any, node);
          }
        }
      }
    }
  });
}

