// hooks/useNearViewport.ts
"use client";
import { useEffect, useLayoutEffect, useRef, useState } from "react";

// P1 lazy-render primitive: flips true once the element scrolls within
// `margin` px of the scroll viewport. Returns [near, placeholderHeightRef] —
// the caller captures the placeholder's height at flip time and compensates
// scroll position for the height delta after upgrading (see TurnCard).
export function useNearViewport(
  ref: React.RefObject<HTMLElement | null>,
  opts: { margin?: number; force?: boolean } = {},
) {
  const { margin = 800, force = false } = opts;
  const [near, setNear] = useState(force);
  const placeholderH = useRef(0);

  useEffect(() => {
    if (near || force) return;
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          placeholderH.current = el.offsetHeight;
          setNear(true);
          io.disconnect();
        }
      },
      { rootMargin: `${margin}px` },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [near, force, margin, ref]);

  // Compensate the scroll container for the placeholder→real height delta so
  // upgrading a card above the viewport doesn't shove the visible text.
  useLayoutEffect(() => {
    if (!near) return;
    const el = ref.current;
    if (!el || !placeholderH.current) return;
    const delta = el.offsetHeight - placeholderH.current;
    placeholderH.current = 0;
    if (!delta) return;
    const container = el.closest<HTMLElement>("[data-thread-scroll]");
    if (!container) return;
    if (el.getBoundingClientRect().top >= container.getBoundingClientRect().top)
      return;
    container.scrollTop += delta;
  }, [near, ref]);

  return near;
}
```

