import { Database } from "bun:sqlite";
import { createElement, Fragment } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import Markdown from "react-markdown";
import { renderCachedMarkdown } from "/data00/home/zhangpeng.pada/trellis/lib/markdown-cache";
import {
  MD_COMPONENTS,
  MD_URL_TRANSFORM,
} from "/data00/home/zhangpeng.pada/trellis/lib/md-components";
import {
  MARKDOWN_REMARK_PLUGINS,
  MARKDOWN_REHYPE_PLUGINS,
} from "/data00/home/zhangpeng.pada/trellis/lib/markdown-plugins";

const db = new Database(`${process.env.HOME}/.trellis/data.db`, { readonly: true });
const rows = db
  .query(
    `SELECT id, response FROM nodes
     WHERE response != '' AND status = 'done'
     ORDER BY LENGTH(response) DESC LIMIT 40`,
  )
  .all() as { id: string; response: string }[];

const totalBytes = rows.reduce((n, r) => n + r.response.length, 0);

function time(label: string, fn: () => void) {
  const t0 = performance.now();
  fn();
  const ms = performance.now() - t0;
  console.log(`${label}: ${ms.toFixed(0)}ms`);
  return ms;
}

// 现状：每次切换都跑完整管线（react-markdown 同步组件）
time("baseline (react-markdown, full pipeline)", () => {
  for (const r of rows) {
    renderToStaticMarkup(
      createElement(
        Markdown,
        {
          remarkPlugins: MARKDOWN_REMARK_PLUGINS,
          rehypePlugins: MARKDOWN_REHYPE_PLUGINS,
          components: MD_COMPONENTS,
          urlTransform: MD_URL_TRANSFORM,
        },
        r.response,
      ),
    );
  }
});

// P0 冷：首次构建 hast 缓存
time("cached cold (build hast + render)", () => {
  for (const r of rows) {
    renderToStaticMarkup(
      createElement(Fragment, null, renderCachedMarkdown(r.id, r.response) as any),
    );
  }
});

// P0 热：重复切换（命中缓存，只跑 toJsxRuntime）
time("cached warm (repeat switch)", () => {
  for (const r of rows) {
    renderToStaticMarkup(
      createElement(Fragment, null, renderCachedMarkdown(r.id, r.response) as any),
    );
  }
});

console.log(`(${rows.length} nodes, ${(totalBytes / 1024).toFixed(0)}KB total)`);

